#!/usr/bin/env python3
"""Multi-page Doré WYSIWYG shell for Homepage and editable Journal."""
import homepage_wysiwyg
import homepage_candidates
import journal_wysiwyg

SUPPORTED={'homepage','homepage-concept-index','homepage-concept-dispatch','homepage-concept-folio','journal-vol-00'}

def render_canvas(page_id='homepage',edit=False):
    if page_id=='homepage':return homepage_wysiwyg.render_canvas(edit=edit)
    if page_id in homepage_candidates.PAGES:return homepage_candidates.render(page_id,edit=edit)
    if page_id=='journal-vol-00':return journal_wysiwyg.render_canvas(edit=edit)
    raise ValueError('wysiwyg_page_not_supported:'+str(page_id))

EDITOR_HTML=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doré Design — Multi-page Editor</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#b9b9b6;color:#171717;font:11px ui-monospace,SFMono-Regular,Menlo,monospace}.top{height:44px;background:#171717;color:#eee;display:flex;align-items:center;gap:7px;padding:0 10px;border-bottom:1px solid #000}.top strong{letter-spacing:.07em}.top a,.top button{color:#eee;background:#303030;border:1px solid #555;padding:6px 9px;text-decoration:none;font:inherit;cursor:pointer}.status{margin-left:auto;color:#d0bd78}.work{height:calc(100% - 44px);display:grid;grid-template-columns:240px minmax(0,1fr) 260px}.side{background:#f3f3ef;overflow:auto;padding:12px;border-right:1px solid #aaa}.right{border-right:0;border-left:1px solid #aaa}.side h3{font-size:10px;letter-spacing:.14em;margin:0 0 10px}.page{padding:9px;border:1px solid #bbb;background:#fff;margin-bottom:7px;cursor:pointer;font-family:Arial,sans-serif}.page.active{border:2px solid #252525;background:#eee8d8}.page b{display:block}.page small{color:#777}.page.unsupported{opacity:.5;cursor:default}.layer{padding:6px 3px;border-bottom:1px solid #ddd;cursor:pointer}.layer:hover,.layer.active{background:#e8dfc8}.canvaswrap{overflow:auto;padding:18px;background:#b9b9b6}.canvas{width:100%;height:100%;border:0;background:white;box-shadow:0 0 0 1px #999}.right label{display:block;margin:12px 0 5px;color:#666}.right textarea{width:100%;min-height:170px;resize:vertical;border:1px solid #aaa;padding:8px;font:13px/1.45 Arial,sans-serif}.right button{width:100%;margin-top:8px;padding:8px;background:#222;color:white;border:0;cursor:pointer}.hint{font:12px/1.5 Arial,sans-serif;color:#555}
</style></head><body><div class="top"><strong>DORÉ DESIGN 1.7 · MULTI-PAGE EDITOR</strong><button id="preview">Preview page</button><a href="/structure-editor">Structure</a><button id="verify">Verify</button><button id="refresh">Refresh</button><span id="status" class="status">loading…</span></div><div class="work"><aside class="side"><h3>PAGES</h3><div id="pages"></div><h3>LAYERS</h3><div id="layers"></div></aside><main class="canvaswrap"><iframe id="canvas" class="canvas"></iframe></main><aside class="side right"><h3>INSPECTOR</h3><div id="empty" class="hint">Select text in the canvas or choose a layer.</div><div id="inspector" hidden><label>PAGE</label><div id="pageid"></div><label>NODE</label><div id="node"></div><label>FIELD</label><div id="field"></div><label>VALUE</label><textarea id="value"></textarea><button id="save">Save field</button></div><p class="hint">Homepage and Journal are separate workspace pages. Editing Journal writes to journal-vol-00, not to a Hugo mirror.</p></aside></div><script>
let ws=null,selected=null;const $=id=>document.getElementById(id),supported=new Set(['homepage','journal-vol-00']);const qs=new URLSearchParams(location.search);let active=qs.get('page')||'homepage';function canvasUrl(){return '/editor-canvas?page='+encodeURIComponent(active)}function previewUrl(){return active==='journal-vol-00'?'/journal/':'/'}async function load(){ws=await(await fetch('/api/workspace',{cache:'no-store'})).json();if(!ws.pages.some(p=>p.id===active&&supported.has(p.id)))active=ws.pages.some(p=>p.id==='homepage')?'homepage':'journal-vol-00';renderPages();renderLayers();$('canvas').src=canvasUrl();$('status').textContent='workspace r'+ws.revision+' · '+active}function renderPages(){$('pages').innerHTML='';for(const p of ws.pages){const d=document.createElement('div');d.className='page '+(p.id===active?'active ':'')+(supported.has(p.id)?'':'unsupported');d.innerHTML='<b>'+p.name+'</b><small>'+p.id+' · '+(p.nodes||[]).length+' layers</small>';if(supported.has(p.id))d.onclick=()=>switchPage(p.id);$('pages').appendChild(d)}}function renderLayers(){const p=ws.pages.find(x=>x.id===active);$('layers').innerHTML='';for(const n of p?.nodes||[]){for(const f of ['text','eyebrow','title','body'])if(n[f]!==undefined){const d=document.createElement('div');d.className='layer';d.textContent=n.id+' · '+f;d.onclick=()=>select(n.id,f,n[f],d);$('layers').appendChild(d)}}}function switchPage(id){active=id;selected=null;history.replaceState(null,'','/editor?page='+encodeURIComponent(active));$('empty').hidden=false;$('inspector').hidden=true;renderPages();renderLayers();$('canvas').src=canvasUrl();$('status').textContent='workspace r'+ws.revision+' · '+active}function select(id,field,value,el){selected={id,field};document.querySelectorAll('.layer').forEach(x=>x.classList.remove('active'));if(el)el.classList.add('active');$('empty').hidden=true;$('inspector').hidden=false;$('pageid').textContent=active;$('node').textContent=id;$('field').textContent=field;$('value').value=value??''}window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='dore-select'&&(!m.page_id||m.page_id===active))select(m.id,m.field,m.value);if((m.type==='dore-ready'||m.type==='dore-saved')&&(!m.page_id||m.page_id===active)){if(m.revision)$('status').textContent=(m.type==='dore-saved'?'saved · ':'workspace r')+m.revision+' · '+active;if(m.type==='dore-saved')refreshWorkspace()}if(m.type==='dore-error')$('status').textContent='ERROR · '+active});async function refreshWorkspace(){ws=await(await fetch('/api/workspace',{cache:'no-store'})).json();renderPages();renderLayers()}$('save').onclick=async()=>{if(!selected)return;const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'set_node',page_id:active,id:selected.id,patch:{[selected.field]:$('value').value}})});if(!r.ok){$('status').textContent='SAVE FAILED';return}ws=await r.json();$('status').textContent='saved · r'+ws.revision+' · '+active;$('canvas').src=canvasUrl();renderLayers()};$('refresh').onclick=()=>{refreshWorkspace();$('canvas').src=canvasUrl()};$('preview').onclick=()=>location.href=previewUrl();$('verify').onclick=async()=>{const v=await(await fetch('/api/verify',{cache:'no-store'})).json();$('status').textContent=v.ok?'VERIFY PASS · r'+v.revision:'VERIFY FAIL'};load();
</script></body></html>'''

EDITOR_HTML=EDITOR_HTML.replace("supported=new Set(['homepage','journal-vol-00'])","supported=new Set(['homepage','homepage-concept-index','homepage-concept-dispatch','homepage-concept-folio','journal-vol-00'])").replace("return active==='journal-vol-00'?'/journal/':'/'","return active==='journal-vol-00'?'/journal/':'/editor-canvas?page='+encodeURIComponent(active)")

PROMOTION_CSS='''<style>.candidate-card{border:1px solid #667;background:#071a28;color:#f2eee4;padding:9px;margin:0 0 7px;cursor:pointer}.candidate-card.on{outline:2px solid #d0bd78}.candidate-card small{display:block;color:#d0bd78;margin-top:4px}.judge-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px}.judge-actions button:last-child{background:#7b2e2e}</style>'''
PROMOTION_PANEL='''<h3>STORYBOOK → DESIGN</h3><div id="candidates"></div><div id="candidate-detail" class="hint"></div>'''
PROMOTION_JUDGMENT='''<h3>CANDIDATE JUDGMENT</h3><div id="judge-empty" class="hint">Choose a promoted candidate.</div><div id="judge-form" hidden><div id="candidate-name"></div><label>WHY</label><textarea id="candidate-reason" placeholder="What belongs—or does not belong—to New Westside?"></textarea><div class="judge-actions"><button id="candidate-accept">Accept</button><button id="candidate-reject">Reject</button></div><button id="candidate-revise">Needs revision</button></div>'''
PROMOTION_JS=r'''<script>(()=>{let catalog={candidates:[]};const $=id=>document.getElementById(id);function current(){return (catalog.candidates||[]).find(c=>c.page_id===active)}function draw(){const box=$('candidates');if(!box)return;box.innerHTML='';for(const c of catalog.candidates||[]){supported.add(c.page_id);const d=document.createElement('div');d.className='candidate-card '+(c.page_id===active?'on':'');d.innerHTML='<b>'+c.name+'</b><small>'+c.runtime_status+' · '+c.source_story_id+'</small>';d.onclick=()=>switchPage(c.page_id);box.appendChild(d)}const c=current();$('judge-empty').hidden=!!c;$('judge-form').hidden=!c;if(c){$('candidate-name').textContent=c.name+' · '+c.runtime_status;$('candidate-reason').value=c.last_judgment?.reason||'';const k=c.knowledge||{},p=k.pattern_judgment||{},v=c.viewport_evidence||{};$('candidate-detail').textContent='ADOPT · '+(p.adopted||[]).join(' / ')+'  REJECT · '+(p.rejected||[]).join(' / ')+'  EVIDENCE · '+Object.keys(v).join(' + ')}}async function reload(){catalog=await fetch('/api/candidates',{cache:'no-store'}).then(r=>r.json());draw()}async function judge(decision){const c=current();if(!c)return;const r=await fetch('/api/candidates/judgment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidate_id:c.id,decision,reason:$('candidate-reason').value,signals:['human-visual-judgment','new-westside-fit']})});const j=await r.json();if(!r.ok){$('status').textContent='JUDGMENT FAILED · '+j.error;return}await reload();$('status').textContent=decision.toUpperCase()+' · returned to Storybook / Knowledge Lab'}$('candidate-accept').onclick=()=>judge('accepted');$('candidate-reject').onclick=()=>judge('rejected');$('candidate-revise').onclick=()=>judge('needs_revision');const oldSwitch=switchPage;switchPage=id=>{oldSwitch(id);draw()};reload()})()</script>'''
EDITOR_HTML=EDITOR_HTML.replace('</head>',PROMOTION_CSS+'</head>').replace('<aside class="side"><h3>PAGES</h3>','<aside class="side">'+PROMOTION_PANEL+'<h3>PAGES</h3>').replace('<aside class="side right"><h3>INSPECTOR</h3>','<aside class="side right">'+PROMOTION_JUDGMENT+'<h3>INSPECTOR</h3>').replace('</body>',PROMOTION_JS+'</body>').replace('DORÉ DESIGN 1.7 · MULTI-PAGE EDITOR','DORÉ DESIGN 1.9 · PROMOTION PIPELINE')

def render_editor(active_page='homepage'):
    return EDITOR_HTML.replace("let active=qs.get('page')||'homepage';",f"let active=qs.get('page')||'{active_page}';",1)
